changeSet.sql:
ALTER TABLE modeling_model_spec
    ADD CONSTRAINT ck_model_spec_dimension_profile
    CHECK (
        dimension_profile IS NULL
        OR (
            contract_version = 2
            AND model_type = 'DIMENSION'
            AND jsonb_typeof(dimension_profile) = 'object'
        )
    );
CREATE UNIQUE INDEX uk_model_spec_v2_dimension_code
    ON modeling_model_spec (tenant_id, lower(dimension_profile ->> 'dimensionCode'))
    WHERE contract_version = 2 AND model_type = 'DIMENSION' AND dimension_profile IS NOT NULL;

rollback.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM modeling_model_spec WHERE dimension_profile IS NOT NULL) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_DIMENSION_PROFILE_DATA_EXISTS';
    END IF;
END $$;
